This Terraform configuration creates a basic AWS RDS MySQL instance using `gp3` storage. It uses the default VPC and its subnets, creates a security group allowing MySQL access on port `3306`, generates a random database password, and provisions the RDS instance with publicly accessible networking for simplicity.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the RDS instance will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "db_name" {
  description = "Initial database name."
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username for the RDS instance."
  type        = string
  default     = "dbadmin"
}

variable "allowed_cidr" {
  description = "CIDR block allowed to connect to the RDS instance on port 3306."
  type        = string
  default     = "0.0.0.0/0"
}

